-- AoTv4 class abilities -- the shared payload behind every class's three disciplines.
--
-- ⚠️⚠️ EVERY BEHAVIOUR LIVES HERE, KEYED BY SPELL ID. The 45 files in quests/global/spells/ are
-- four-line stubs that call M.fire; they are GENERATED by custom/tools/gen_class_abilities.py along
-- with the migrations, so editing one by hand is reverted the next time that runs. 45 near-identical
-- scripts would be 45 chances for the cost model, the cooldown cut and the swing to drift apart.
--
-- ⚠️⚠️ A DISCIPLINE'S RECAST IS KEYED ON `EndurTimerIndex`, NOT ON THE SPELL ID. CastSpell's
-- per-spell branch is guarded by `&& !spells[spell_id].is_discipline`, so pTimerSpellStart is never
-- started for one. Everything below that touches a cooldown uses the TIMER id.
--
-- ⚠️⚠️ THE PAYLOAD RUNS **BEFORE** THE SPELL APPLIES ITS OWN EFFECTS. The event fires at
-- spell_effects.cpp:163 and the effect-slot loop starts at :225, so a payload never sees its own
-- SPAs land -- a pet summoned by SPA 33 does not exist yet, and a buff's stat changes have not
-- happened. ⚠️ Returning non-zero from the event CANCELS the effects outright, so no payload may
-- return a value.

local M = {}

-- Three timer slots serve all sixteen classes: a character is only ever one class, so nobody can
-- hold two tier 1s. ⚠️ Only 0-10 are valid -- 11 collides with pTimerCombatAbility (Kick/Bash).
-- ⚠️ Not sequential on purpose: 1/4/7/8/9 carry stock discs reachable at our level cap.
M.TIMER = { [1] = 5, [2] = 6, [3] = 2 }

-- Flat cost model, charged here because EndurCost cannot scale.
-- ⚠️⚠️ ONLY FOR ABILITIES THAT ARE **NOT** A SWING. Anything routed through M.weapon_blow already
-- pays section 22's charge -- 33 percent of the damage dealt -- inside DoSpecialAttackDamage, and
-- charging both bills one swing twice. Design section 2b: the two models are chosen by what the
-- ability is and are never combined. M.SPEC below records which abilities take a flat cost.
M.COST_PER_LEVEL = { [1] = 1, [2] = 5, [3] = 2 }

-- ⚠️ The resource follows the ability, not the tier: endurance for the melee classes, mana for the
-- casters, and HEALTH for the Necromancer, which is the class that should be paying in it.
-- ⚠️⚠️ A discipline CANNOT carry a mana cost on its row -- IsDiscipline is `mana = 0 AND
-- EndurCost > 0`, so a caster's cost has to be taken here or the ability stops being a discipline
-- and leaves the Combat Abilities window entirely.
M.RESOURCE = {
	[1]="end", [3]="end", [4]="end", [5]="end", [7]="end", [8]="end", [9]="end", [15]="end", [16]="end",
	[2]="mana", [6]="mana", [10]="mana", [12]="mana", [13]="mana", [14]="mana",
	[11]="hp",
}

M.BUILT = { [1]=true, [2]=true, [3]=true, [4]=true, [5]=true, [6]=true, [7]=true, [8]=true, [9]=true,
            [10]=true, [11]=true, [12]=true, [13]=true, [14]=true, [15]=true, [16]=true }
-- ⚠️⚠️ PALADIN (3) IS IN THE LIST AS OF 2026-08-21, AND ITS THREE ACTIVATED AAs MUST BE RETIRED IN
-- THE SAME DEPLOY (migration 2026_08_21_paladin_retire_aas). It was the last class on a different
-- mechanism -- one class finding its kit in the AA window while fifteen found theirs in Combat
-- Abilities -- and that inconsistency is why it was converted. Ship one without the other and a
-- Paladin holds each ability twice.

M.TIER_LEVEL = { 1, 5, 10 }

function M.spell_id(class, tier) return 44700 + (class - 1) * 3 + (tier - 1) end
function M.tier_of(spell_id)
	if spell_id < 44700 or spell_id > 44747 then return nil end
	return ((spell_id - 44700) % 3) + 1
end
function M.class_of(spell_id)
	if spell_id < 44700 or spell_id > 44747 then return nil end
	return math.floor((spell_id - 44700) / 3) + 1
end

-- ⚠️ Resolve a caster through the entity list. `e.caster_id` gives a Lua_Mob, and CharacterID is
-- only defined on Lua_Client -- calling it on a Mob is a nil-value error at runtime with nothing to
-- warn you at write time (section 24).
function M.as_client(mob)
	if not mob then return nil end
	local ent = eq.get_entity_list()
	if not ent then return nil end
	return ent:GetClientByID(mob:GetID())
end

-- ---------------------------------------------------------------------------------------------
-- Cost, refund, cooldown

function M.charge(c, tier)
	local per = M.COST_PER_LEVEL[tier]
	if not per then return true end
	local cost = per * c:GetLevel()
	local res  = M.RESOURCE[c:GetClass()] or "end"

	if res == "mana" then
		if (c:GetMana() or 0) < cost then c:Message(13, "You lack the focus.") return false end
		c:SetMana(c:GetMana() - cost)
	elseif res == "hp" then
		-- ⚠️ Paying in health must never be able to kill you: a cost that can finish you off makes
		-- the ability unusable exactly when it matters. Floor it at 1.
		if (c:GetHP() or 0) <= cost then c:Message(13, "You are too close to death.") return false end
		c:SetHP(c:GetHP() - cost)
	else
		-- ⚠️ There is no AddEndurance binding, only Get/Set, so the floor is applied by hand or a
		-- cast at an empty bar sets endurance negative.
		if (c:GetEndurance() or 0) < cost then c:Message(13, "You are too winded.") return false end
		c:SetEndurance(c:GetEndurance() - cost)
	end
	return true
end

-- ⚠️⚠️ HAND THE COOLDOWN BACK WHEN AN ABILITY REFUSES ITSELF AFTER THE CAST HAS ALREADY HAPPENED.
-- `UseDiscipline` only checks the row's EndurCost, which is a token 1 (the real cost is level-scaled
-- and paid in M.charge), and it starts the recast BEFORE the payload runs. So a player one point
-- short would otherwise land the ability, be told they cannot pay, and lose the whole cooldown for
-- nothing. Clearing the timer is the only refund path there is.
function M.refund(c, tier)
	return c:AoTv4ReduceDisciplineTimer(M.TIMER[tier], 100000)
end

-- Shorten this character's tier-2 cooldown. ⚠️ Takes the TIMER id, not the spell id.
function M.cut_tier2(c, seconds)
	if not seconds or seconds <= 0 then return false end
	return c:AoTv4ReduceDisciplineTimer(M.TIMER[2], seconds)
end

-- ---------------------------------------------------------------------------------------------
-- Granting

-- ⚠️⚠️ THE ROGUELITE DEATH WIPES TRAINED DISCIPLINES -- death_loss calls UntrainDiscAll, and they
-- live in character_disciplines, not the spellbook. So this must run on death as well as on connect
-- and on level up, or a character comes back from every run with no class abilities at all. Class
-- AAs are permanent and need no such hook, which is why grant_class_aas has only two callers.
function M.grant(c)
	if not c then return end
	local class = c:GetClass()
	if not M.BUILT[class] then return end
	for tier = 1, 3 do
		local id = M.spell_id(class, tier)
		if c:GetLevel() >= M.TIER_LEVEL[tier] and not c:HasDisciplineLearned(id) then
			-- ⚠️ TrainDiscBySpellID validates NOTHING -- not class, not level, not whether you
			-- already know it (zone/effects.cpp:883). It fills the first empty slot, so a second
			-- call would list the same ability twice. This guard is the only thing stopping that.
			c:TrainDiscBySpellID(id)
			c:Message(15, string.format("You have learned %s.", eq.get_spell_name(id)))
		end
	end
end

-- ---------------------------------------------------------------------------------------------
-- The shared swing
--
-- ⚠️⚠️ ROUTE EVERY BLOW THROUGH DoSpecialAttackDamage. It is the choke point Kick, Bash, Frenzy and
-- the monk strikes all use, so the blow inherits mitigation, avoidance, the damage packet, skill
-- procs and section 22's damage-proportional endurance charge. Rolling damage by hand inherits none.
-- ⚠️⚠️ IT TAKES AT MOST SIX ARGUMENTS (other, skill, base_damage, min_damage, hate_override,
-- reuse_seconds). A seventh matches no overload and is a luabind error at runtime.
-- ⚠️⚠️ THE SKILL IS THE EQUIPPED WEAPON'S OWN SKILL. `my_hit.offense` and `GetTotalToHit` are both
-- computed from the skill argument (special_attacks.cpp:296), and on this server a character may
-- genuinely have 0 in a special's skill (section 4: a cap exists for every class, the VALUE is only
-- granted if native or picked). Naming an untrained skill quietly wrecks the to-hit roll, and it
-- makes the client's damage message read as that special rather than as a weapon hit.
local SKILL_OF_ITEMTYPE = {
	[0]  = 1,    -- 1H Slash    -> Skill1HSlashing
	[1]  = 3,    -- 2H Slash    -> Skill2HSlashing
	[2]  = 36,   -- 1H Pierce   -> Skill1HPiercing
	[3]  = 0,    -- 1H Blunt    -> Skill1HBlunt
	[4]  = 2,    -- 2H Blunt    -> Skill2HBlunt
	[35] = 77,   -- 2H Pierce   -> Skill2HPiercing
}
local SKILL_HAND_TO_HAND = 28
local SKILL_ARCHERY      = 7
local SLOT_PRIMARY       = 13
local SLOT_RANGE         = 11
local ITEMTYPE_BOW       = 5

-- Returns skill, base_damage, delay for whatever is in the primary slot.
-- ⚠️ GetItemIDAt returns INVALID_ID (-1) for an empty slot, NOT 0.
function M.weapon_profile(c)
	local id = c:GetItemIDAt(SLOT_PRIMARY)
	if not id or id <= 0 then
		return SKILL_HAND_TO_HAND, math.max(1, math.floor(c:GetLevel() / 2)), 36
	end
	local itemtype = eq.get_item_stat(id, "itemtype") or -1
	local dmg      = eq.get_item_stat(id, "damage") or 0
	local delay    = eq.get_item_stat(id, "delay") or 36
	-- 📌 Reading the ITEM ID means gear tiers are already counted: a Hallowed or Mythic copy is its
	-- own row with its own damage column (section 10), so nothing here has to know tiers exist.
	return SKILL_OF_ITEMTYPE[itemtype] or SKILL_HAND_TO_HAND,
	       math.max(1, dmg + math.floor(c:GetLevel() / 2)), math.max(1, delay)
end

function M.has_bow(c)
	local id = c:GetItemIDAt(SLOT_RANGE)
	if not id or id <= 0 then return false end
	return (eq.get_item_stat(id, "itemtype") or -1) == ITEMTYPE_BOW
end

-- 📌 Damage is `weapon damage + level/2`, about twice a Frenzy swing (Frenzy is weapon damage / 2,
-- special_attacks.cpp:70). First-pass tuning; `mult` lets one ability hit harder than another
-- without every payload re-deriving the formula.
-- ⚠️ hate_override is passed as -1 ("use the damage") rather than a number, because
-- `AoT:SpecialBonusThreat` overwrites it for every non-Bash special anyway (special_attacks.cpp:293).
-- An ability that wants threat adds it EXPLICITLY afterwards.
function M.weapon_blow(c, target, reuse_seconds, mult, skill_override)
	if not c or not target or not target.valid then return false end
	local skill, base = M.weapon_profile(c)
	base = math.max(1, math.floor(base * (mult or 1.0)))
	local used = skill_override or skill
	c:DoSpecialAttackDamage(target, used, base, 1, -1, reuse_seconds or 0)
	-- ⚠️⚠️ DoSpecialAttackDamage DOES NOT TRAIN THE SKILL -- it contains no CheckIncreaseSkill at all.
	-- Every stock special calls it separately AFTER the damage (Bash at special_attacks.cpp:533,
	-- Frenzy :563, Kick :696, Backstab :899), which is easy to miss because the call sites look like
	-- part of the special rather than part of the swing. Without this these abilities are the only
	-- melee attacks in the game that never raise the weapon skill they use.
	-- 📌 chance_mod 10, matching every stock special.
	c:CheckIncreaseSkill(used, target, 10)
	return true
end

-- ⚠️⚠️ AN AoE MUST NOT PICK ITS TARGETS BY PROXIMITY ALONE. IsAttackAllowed says the banker behind
-- your target CAN be hit, not that it should be, and one cleave through a town is a KOS faction hit
-- nobody asked for (section 28). Every sweep is limited to the creature you are actually fighting
-- and anything already holding you on its hate list.
-- ⚠️ `for m in list.entries do` -- a Lua_NPC_List is NOT an array, so ipairs() yields nothing.
-- ⚠️ `frontal` uses `not BehindMob`, a 180 degree arc: Mob::InFrontMob (the 56 degree one) HAS NO
-- LUA BINDING on this build. MobAngle reads the HEADING OF THE ARGUMENT and the position passed in,
-- so the caster must be the argument and the creature's own coordinates the point.
function M.sweep(c, range, frontal)
	local out = {}
	local tgt = c:GetTarget()
	local list = eq.get_entity_list():GetNPCList()
	for m in list.entries do
		if m and m.valid and m:GetHP() > 0 and c:IsAttackAllowed(m)
		   and (m:CheckAggro(c) or (tgt and tgt.valid and m:GetID() == tgt:GetID()))
		   and c:CalculateDistance(m:GetX(), m:GetY(), m:GetZ()) <= range
		   and ((not frontal) or (not m:BehindMob(c, m:GetX(), m:GetY()))) then
			out[#out + 1] = m
		end
	end
	return out
end

-- ---------------------------------------------------------------------------------------------
-- Pets -- Magician and Beastlord
--
-- ⚠️⚠️ THE ABILITY GRANTS THE PET RATHER THAN DEPENDING ON ONE. Pets normally come from spells, and
-- on a random-progression server a Magician may simply never be offered one -- an ability that waits
-- on a random reward is not an ability.
-- ⚠️⚠️ A PET'S STATS ARE FROZEN AT SUMMON (Mob::MakePet, pets.cpp:140), which is the same reason
-- SPA 213 PetMaxHP does nothing to a pet you already have. "Levels with you" therefore has to be a
-- rescale, and it is applied here on every press and from global_player on every level up.
-- ⚠️ SpellFinished, NOT CastSpell: the helper rows are classes 255 for everyone (they are cast BY
-- something, never by a player), so a real cast would be refused on the class gate.
function M.ensure_pet(c, pet_spell)
	local p = c:GetPet()
	if p and p.valid then M.rescale_pet(c) return false end
	c:SpellFinished(pet_spell, c)
	return true
end

function M.rescale_pet(c)
	local p = c:GetPet()
	if not p or not p.valid then return end
	local lvl = c:GetLevel()
	if p:GetLevel() == lvl then return end          -- deadband: nothing to do on most presses
	local n = p:CastToNPC()
	if not n then return end
	-- ⚠️ ModifyNPCStat takes STRINGS, and ScaleNPC is deliberately NOT used: it rewrites the stat
	-- block wholesale from npc_scale_global_base and would throw away everything set here.
	n:ModifyNPCStat("level",   tostring(lvl))
	n:ModifyNPCStat("max_hp",  tostring(40 * lvl))
	n:ModifyNPCStat("min_hit", tostring(lvl))
	n:ModifyNPCStat("max_hit", tostring(lvl * 3))
	n:ModifyNPCStat("ac",      tostring(lvl * 4))
	n:ModifyNPCStat("atk",     tostring(lvl * 5))
	-- ⚠️ max_hp clamps DOWN only -- raising the maximum does not raise current health, so without
	-- this the pet levels up and stays wounded.
	p:SetHP(p:GetMaxHP())
end

-- ---------------------------------------------------------------------------------------------
-- Warrior tier 2 -- Bulwark. The absorb is paid here because SPA 162's per-hit cap is a fixed
-- number on the spell row and this one is `AC / 10`, which is per character and per moment.
--
-- ⚠️⚠️ THE CHARGES ARE COUNTED HERE, NOT BY THE ENGINE, AND THAT IS NOT A PREFERENCE.
-- `numhits`/`numhitstype 6` would give a free client-side counter, but the engine spends the last
-- charge and FADES THE BUFF in CheckNumHitsRemaining (attack.cpp:4621) -- which runs BEFORE
-- EVENT_DAMAGE_TAKEN (attack.cpp:4689) in the same Mob::CommonDamage call. So on the fifth hit the
-- payload would find no buff and absorb nothing: an ability that advertises five absorbs and
-- delivers four, silently. **Any Lua-paid charge effect has this problem; count it yourself.**
local BULWARK_SPELL   = 44701
local BULWARK_CHARGES = 5
local BULWARK_VAR     = "aotv4_bulwark"

-- ⚠️⚠️ THIS RUNS ON EVERY DAMAGE EVENT FOR EVERY PLAYER. The arithmetic early-outs come first,
-- before the entity-variable lookup and long before FindBuff walks the buff slots (section 5).
-- ⚠️⚠️ THE RETURN VALUE IS A DAMAGE OVERRIDE: positive REPLACES the damage, negative NEGATES the
-- hit, and nil leaves it alone (attack.cpp:4706). Reducing a blow to exactly nothing therefore means
-- returning a negative, not returning 0.
function M.on_damage_taken(e)
	local dmg = e.damage or 0
	if dmg <= 0 then return end
	-- Melee only: Mob::Damage defaults spell_id to SPELL_UNKNOWN, so a swing carries 0 or 65535.
	if not (e.spell_id == 0 or e.spell_id == 65535) then return end

	local c = e.self
	if not c or not c.valid or not c:IsClient() then return end

	local left = tonumber(c:GetEntityVariable(BULWARK_VAR) or "") or 0
	if left <= 0 then return end

	-- ⚠️ The counter is an ENTITY variable, so it does not survive zoning while the buff does. The
	-- buff is the authority on whether the ability is still up: no buff means the count is stale.
	if not c:FindBuff(BULWARK_SPELL) then
		c:SetEntityVariable(BULWARK_VAR, "0")
		return
	end

	local absorb = math.floor((c:GetAC() or 0) / 10)
	if absorb < 1 then absorb = 1 end

	left = left - 1
	c:SetEntityVariable(BULWARK_VAR, tostring(left))
	if left <= 0 then
		c:BuffFadeBySpellID(BULWARK_SPELL)
		c:Message(15, "Your bulwark is spent.")
	end

	if absorb >= dmg then return -1 end
	return dmg - absorb
end

-- ---------------------------------------------------------------------------------------------
-- Wizard Ley Tap stacks, counted the same way and for the same reason.
local LEYTAP_VAR, LEYTAP_MAX = "aotv4_leytap", 3

-- ---------------------------------------------------------------------------------------------
-- SPEC: what M.fire does for an ability before its payload runs.
--   cost = the tier whose flat cost this ability pays, or nil for a swing (which pays section 22)
--   buff = a self buff, so a refused cost must fade it as well as refund the cooldown
local S = function(cost, buff) return { cost = cost, buff = buff } end
M.SPEC = {
	-- Warrior
	[44700]=S(nil), [44701]=S(2,true), [44702]=S(nil),
	-- Paladin (tiers 1 and 3 are swings, so only the heal takes a flat cost)
	[44706]=S(nil), [44707]=S(2), [44708]=S(nil),
	-- Cleric            Ranger              Shadowknight
	[44703]=S(nil), [44704]=S(2), [44705]=S(3),
	[44709]=S(nil), [44710]=S(nil), [44711]=S(nil),
	[44712]=S(nil), [44713]=S(nil), [44714]=S(nil),
	-- Druid
	[44715]=S(nil), [44716]=S(2), [44717]=S(3),
	-- Monk
	[44718]=S(nil), [44719]=S(2,true), [44720]=S(nil),
	-- Bard
	[44721]=S(nil), [44722]=S(2), [44723]=S(nil),
	-- Rogue
	[44724]=S(nil), [44725]=S(2), [44726]=S(nil),
	-- Shaman
	[44727]=S(1), [44728]=S(2), [44729]=S(3),
	-- Necromancer
	[44730]=S(nil), [44731]=S(2), [44732]=S(3),
	-- Wizard
	[44733]=S(nil), [44734]=S(2), [44735]=S(3),
	-- Magician
	[44736]=S(nil), [44737]=S(2,true), [44738]=S(3),
	-- Enchanter (tier 1 is Tashania, the one tier 1 that is not a swing)
	[44739]=S(1), [44740]=S(2), [44741]=S(3,true),
	-- Beastlord
	[44742]=S(nil), [44743]=S(2,true), [44744]=S(nil),
	-- Berserker
	[44745]=S(nil), [44746]=S(2), [44747]=S(nil),
}

-- ---------------------------------------------------------------------------------------------
-- PAYLOAD: everything an ability does beyond its own spell effects. Nil = the row does it all.
local P = {}
M.PAYLOAD = P

-- ============================================================== 1 WARRIOR
P[44700] = function(c, t)                                    -- Cleaving Blow
	if not M.weapon_blow(c, t, 10) then return end
	-- Threat is added EXPLICITLY: AoT:SpecialBonusThreat floors the bonus hate of every non-Bash
	-- special to a token 1 inside DoSpecialAttackDamage, so a hate_override would be overwritten.
	t:AddToHateList(c, c:GetLevel() * 6)
end
P[44701] = function(c)                                       -- Bulwark
	c:SetEntityVariable(BULWARK_VAR, tostring(BULWARK_CHARGES))
	c:Message(15, "You set yourself behind your guard.")
end
P[44702] = function(c)                                       -- Broad Cleave
	local hit = M.sweep(c, 30, true)
	for _, m in ipairs(hit) do
		-- ⚠️⚠️ NO AddToHateList HERE, DELIBERATELY. An AoE that pulls everything you were not
		-- fighting is the exact "spamming it is both optimal and wrong" trap the tier 3 rule exists
		-- to avoid. The damage still generates ordinary threat inside Mob::Damage.
		M.weapon_blow(c, m, 15)
	end
	-- ⚠️⚠️ THE CUT IS EARNED BY HITTING SOMETHING, NOT BY PRESSING THE BUTTON.
	if #hit > 0 then M.cut_tier2(c, math.min(#hit * 3, 9)) end
end

-- ============================================================== 2 CLERIC
P[44703] = function(c, t)                                    -- Templar Strike
	if not M.weapon_blow(c, t, 10) then return end
	-- ⚠️ DoSpecialAttackDamage returns void, so the damage actually dealt is unknowable from Lua.
	-- Every "a share of the damage" rider in this file is therefore a LEVEL-scaled flat amount.
	c:HealDamage(c:GetLevel() * 2, c)
end
P[44705] = function(c, t)                                    -- Condemn
	-- bodytype 3 is Undead. The nuke itself is on the spell row; this is only the cut.
	M.cut_tier2(c, (t and t:GetBodyType() == 3) and 10 or 5)
end

-- ============================================================== 3 PALADIN
-- Ported from lua_modules/aotv4_paladin.lua, which drove the retired AA versions. Only the delivery
-- changed; the tuning and the reasons for it are unchanged.
-- ⚠️⚠️ ALL THREE EFFECTS ARE HERE RATHER THAN ON THE ROW BECAUSE NONE CAN BE EXPRESSED IN
-- `spells_new`: Ardent Strike scales with STRENGTH (no SPA reads a caster stat as its magnitude),
-- Hand of Conviction heals a percentage of the CASTER's max HP (SPA 147 is a percentage of the
-- TARGET's, a different spell entirely), and the cooldown cut reaches a recast timer, which nothing
-- in the spell system does.
local PAL_PER_LEVEL, PAL_PER_STR = 1, 0.10
local PAL_CONVICTION_PCT = 0.25

P[44706] = function(c, t)                                    -- Ardent Strike
	-- ⚠️ Deliberately WEAKER than Cleaving Blow (0.8): the Paladin trades swing damage for the heal
	-- and the taunt. It goes through the same M.weapon_blow as every other tier 1.
	if not M.weapon_blow(c, t, 10, 0.8) then return end
	-- ⚠️ KEEP THE BONUS SMALL. It is unmitigated -- Mob::Damage does NOT run MeleeMitigation, that
	-- lives in Mob::Attack -- so every point is a point the target cannot reduce. An earlier version
	-- computed max(level*3, STR*0.75) and applied it this way, which read as ~150 at level 15 and was
	-- reported from play as hitting far too hard.
	-- ⚠️ Both halves are needed: Strength alone is useless at level 1 (a naked character's STR does
	-- not rise with level -- stats come entirely from gear here), and a level floor alone would make
	-- Strength pointless forever.
	local bonus = math.max(c:GetLevel() * PAL_PER_LEVEL, math.floor((c:GetSTR() or 0) * PAL_PER_STR))
	if bonus > 0 then
		-- ⚠️ spell_id 0, not the ability id: passing it would report this as MAGIC damage and let
		-- spell-damage modifiers touch it. This is the divine part of a weapon blow.
		t:Damage(c, bonus, 0, 10, false)
	end
	t:AddToHateList(c, c:GetLevel() * 8)
end

P[44707] = function(c)                                       -- Hand of Conviction
	local amount = math.floor((c:GetMaxHP() or 0) * PAL_CONVICTION_PCT)
	if amount <= 0 then return end

	local grp = c:GetGroup()
	if not grp or not grp.valid then
		-- Solo heals the Paladin. An ability worth nothing without a group would be dead weight for
		-- most of a run, and soloing is normal here.
		c:HealDamage(amount, c)
		c:Message(15, string.format("Your conviction restores %d hit points.", amount))
		return
	end

	-- ⚠️ GetMember hands back a Lua_Mob and only members IN THIS ZONE resolve through the entity
	-- list. A member elsewhere is simply not healed; there is no cross-zone heal.
	local healed = 0
	for i = 0, (grp:GroupCount() or 0) - 1 do
		local m = grp:GetMember(i)
		if m and m.valid then
			local mc = eq.get_entity_list():GetClientByID(m:GetID())
			if mc and mc.valid then
				mc:HealDamage(amount, c)
				healed = healed + 1
			end
		end
	end
	c:Message(15, string.format("Your conviction restores %d hit points to %d in your group.",
		amount, healed))
end

P[44708] = function(c, t)                                    -- Divine Reproach
	-- ⚠️ The stun is the row's own SPA 21, so the engine owns resist, immunity and the message.
	-- 📌 The design asks for the cut "only if the stun lands", and that is NOT observable here: the
	-- payload runs BEFORE the spell applies its own effects, so the stun has not been rolled yet.
	-- Same limitation as the Monk's crit-doubled cut. It cuts on a landed swing instead.
	if not M.weapon_blow(c, t, 15) then return end
	t:AddToHateList(c, c:GetLevel() * 6)
	M.cut_tier2(c, 5)
end

