P[44745] = function(c, t)                                    -- Reckless Cleave
	if not M.weapon_blow(c, t, 10, 1.4) then return end
	-- ⚠️ Self damage must never be able to kill you -- an ability that can finish you off is one
	-- nobody presses. SetHP, not Damage: Damage would put the Berserker on their own hate list.
	local bleed = math.max(1, math.floor(c:GetMaxHP() * 0.01))
