	-- 2 seconds per tenth of health missing: fully wounded is the full 18, untouched is nothing.
	local missing = 100 - (c:GetHPRatio() or 100)
	M.cut_tier2(c, math.floor(missing / 10) * 2)
end

-- ---------------------------------------------------------------------------------------------
-- The Class Abilities WINDOW (dll: core_abilities.cpp).
--
-- ⚠️⚠️ THIS IS NOT A CONVENIENCE DUPLICATE OF THE STOCK COMBAT ABILITIES WINDOW. That window will
-- not open at all for a caster on this client, so for eleven of the sixteen classes this is the only
-- way to click these. See core_abilities.h for the disassembly that went looking for a class gate.
--
-- Protocol: server -> "ABILDATA <n>^spellid|name|tier|unlocked|ready_secs|reuse_secs^..."
--           client -> "/say abiluse <spellid>" , "/say abilrefresh"
-- ⚠️ The description rides on the SAME row rather than as a second line: three abilities of ~150
-- characters is well inside Client::Message's 4096 byte buffer, and a second line would be a second
-- chance for the RoF2 chat pipe to drop or reorder it (section 15).
M.RECAST_SECS = { [1] = 10, [2] = 120, [3] = 15 }

-- ⚠️ GENERATED alongside the db_str rows by custom/tools/gen_class_abilities.py, so the window text
-- and the spellbook text come from one spec. There is no Lua binding to read db_str, and hand
-- copying the strings would be two sources of truth.
local DESC = require("aotv4_class_ability_desc")

function M.send_data(c)
	if not c then return end
	local class = c:GetClass()
	if not M.BUILT[class] then
		c:Message(15, "Your class has no class abilities.")
		return
	end

	local rows, n = "", 0
	for tier = 1, 3 do
		local id       = M.spell_id(class, tier)
		local unlocked = (c:GetLevel() >= M.TIER_LEVEL[tier] and c:HasDisciplineLearned(id)) and 1 or 0

		-- ⚠️ Client::GetDisciplineTimer already guards on the timer being enabled and returns 0 when
		-- it is not -- but clamp anyway: section 19 records PersistentTimer::GetRemainingTime
		-- answering 0xFFFFFFFF for a timer that EXISTS but is DISABLED, which displays as a 49 day
		-- cooldown on an ability that is actually ready.
		local ready = c:GetDisciplineTimer(M.TIMER[tier]) or 0
		if ready < 0 or ready > 86400 then ready = 0 end

		rows = rows .. string.format("^%d|%s|%d|%d|%d|%d|%s",
			id, eq.get_spell_name(id), tier, unlocked, ready, M.RECAST_SECS[tier],
			DESC[id] or "")
		n = n + 1
	end
	c:Message(15, string.format("ABILDATA %d%s", n, rows))
end

-- ⚠️ Routed through UseDiscipline, the SAME entry point the stock hotbutton uses, so the level gate,
-- the endurance cost and the recast timer all still apply. A modified client gains nothing.
function M.handle_say(c, msg)
	if not c or not msg then return false end
	if msg == "abilrefresh" then
		M.send_data(c)
		return true
	end
	local id = msg:match("^abiluse%s+(%d+)$")
	if id then
		id = tonumber(id)
		-- ⚠️ Bounded to OUR band. Without this the window becomes a way to fire any discipline in the
		-- game by id, which a modified client would happily do.
		if id and id >= 44700 and id <= 44747 then
			local tgt = c:GetTarget()
			c:UseDiscipline(id, (tgt and tgt.valid) and tgt:GetID() or c:GetID())
		end
		return true
	end
	return false
end

-- ---------------------------------------------------------------------------------------------
-- The one entry point every stub calls.
--
-- ⚠️⚠️ THE COST IS TAKEN AFTER THE ABILITY HAS ALREADY LANDED, so a refusal must hand back BOTH the
-- buff and the cooldown. UseDiscipline checks only the row's token EndurCost of 1 and starts the
-- recast before this runs.
function M.fire(spell_id, e)
	-- ⚠️⚠️ `e.target`, NOT `e.self`. A SPELL event sets exactly six fields -- target, spell_id,
	-- caster_id, tics_remaining, caster_level, buff_slot, spell (`handle_spell_event`,
	-- zone/lua_parser_events.cpp:2081) -- and **`self` is not one of them**. Reading e.self gives nil,
	-- so every targeted ability silently did nothing: M.weapon_blow returns false on a nil target and
	-- the swing never happens. Only the self-buffs, which ignore the target, appeared to work.
	-- 📌 `e.self` IS correct in the DAMAGE hooks below -- a different event builder, different fields.
	-- The two look identical at the call site and are not.
	local target = e.target
	local caster = M.as_client(eq.get_entity_list():GetMobID(e.caster_id))
	if not caster then return end

	local spec = M.SPEC[spell_id]
	if spec and spec.cost then
		if not M.charge(caster, spec.cost) then
			if spec.buff then caster:BuffFadeBySpellID(spell_id) end
			M.refund(caster, spec.cost)
			return
		end
	end

	local fn = P[spell_id]
	if fn then fn(caster, target, e) end
	-- ⚠️ NO RETURN VALUE. Returning non-zero from EVENT_SPELL_EFFECT_* cancels the spell's own
	-- effects (spell_effects.cpp:172), which would silently delete every native half of these rows.
end

return M
